"""Customer insight endpoints for the account team."""

from __future__ import annotations

from typing import Any

from orders.application.customer_service import CustomerService
from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found, require_positive_int


class CustomerInsightsController:
    def __init__(self, orders: OrderService, customers: CustomerService) -> None:
        self._orders = orders
        self._customers = customers

    def handle_order_history(self, customer_id: str) -> Response:
        try:
            summaries = self._orders.order_history(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        order_entries: list[dict[str, Any]] = [
            {"order_id": s.order.order_id, "status": s.order.status, "total_cents": s.total_cents}
            for s in summaries
        ]
        return Response(200, {"customer_id": customer_id, "orders": order_entries})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        """Non-cancelled order count and the sum of their totals (discounts included)."""
        try:
            order_count, value = self._lifetime_value(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {
            "customer_id": customer_id,
            "order_count": order_count,
            "lifetime_value_cents": value,
        })

    def handle_top_customers(self, limit: Any) -> Response:
        """Customers ranked by lifetime value, highest first; zero-value customers are omitted."""
        try:
            limit = require_positive_int(limit, "limit")
        except InvalidRequest as exc:
            return bad_request(exc)
        ranked = []
        for customer in self._customers.list_all():
            _, value = self._lifetime_value(customer.customer_id)
            if value > 0:
                ranked.append((value, customer))
        ranked.sort(key=lambda pair: (-pair[0], pair[1].customer_id))
        return Response(200, {"customers": [
            {"customer_id": c.customer_id, "name": c.name, "lifetime_value_cents": value}
            for value, c in ranked[:limit]
        ]})

    def _lifetime_value(self, customer_id: str) -> tuple[int, int]:
        """Return (non-cancelled order count, sum of their totals). Raises CustomerNotFound."""
        summaries = self._orders.order_history(customer_id)
        active = [s for s in summaries if s.order.status != "cancelled"]
        return len(active), sum(s.total_cents for s in active)

